 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    rectangles = []
    for color in range(10):
        if color == bg:
            continue
        # 2-D prefix sums make exhaustive rectangle scoring inexpensive.
        p = [[0] * (w + 1) for _ in range(h + 1)]
        for r in range(h):
            for c in range(w):
                p[r+1][c+1] = (p[r][c+1] + p[r+1][c] - p[r][c]
                                + (grid[r][c] == color))
        best = []
        for r0 in range(h):
            for r1 in range(r0 + 1, h + 1):
                for c0 in range(w):
                    for c1 in range(c0 + 1, w + 1):
                        area = (r1-r0)*(c1-c0)
                        if area < 6:
                            continue
                        count = p[r1][c1]-p[r0][c1]-p[r1][c0]+p[r0][c0]
                        if count / area >= 0.65:
                            # Favor the full rectangle, but penalize unsupported extensions.
                            score = count - 0.5*area
                            if score > 0:
                                best.append((score, count/area, area, r0, r1, c0, c1, color))
        rectangles.extend(best)
    rectangles.sort(reverse=True)
    chosen = []
    for cand in rectangles:
        score, density, area, r0, r1, c0, c1, color = cand
        # Ignore alternate subrectangles of a region already identified.
        if any(max(0, min(r1, b)-max(r0, a)) * max(0, min(c1, d)-max(c0, c)) >= 0.5*area
               for a,b,c,d,k in chosen):
            continue
        chosen.append((r0,r1,c0,c1,color))
    out = [[bg for _ in range(w)] for _ in range(h)]
    for r0,r1,c0,c1,color in chosen:
        for r in range(r0,r1):
            for c in range(c0,c1):
                out[r][c] = color
    return out
